When('the Super Admin leaves {string} blank on the Create Ranch Admin form and attempts to submit', async function (
  this: ScenarioContext,
  fieldName: string,
) {
  const row = this.testData as Record<string, string>;
  const password = row.PasswordKey ? resolvePassword(row.PasswordKey) : 'Pass0123';
  const fullName = fieldName === 'Full Name' ? '' : row.FullName || 'Jordan Hayes';
  const email = fieldName === 'Email' ? '' : row.Email || 'jordan.hayes.qa@ranchops-test.com';
  const pwd = fieldName === 'Password' ? '' : password;
  if (fieldName !== 'Assign to Ranch') {
    await this.superAdminPage.openCreateAdminModal();
    await this.superAdminPage.fullNameInput.fill(fullName);
    await this.superAdminPage.emailInput.fill(email);
    await this.superAdminPage.passwordInput.fill(pwd);
    if (row.AssignRanch) {
      await this.superAdminPage.assignToRanchDropdown.click();
      await this.superAdminPage.assignToRanchOption(row.AssignRanch).click();
    }
  } else {
    await this.superAdminPage.openCreateAdminModal();
    await this.superAdminPage.fullNameInput.fill(fullName);
    await this.superAdminPage.emailInput.fill(email);
    await this.superAdminPage.passwordInput.fill(password);
  }
  await this.superAdminPage.submitCreateAdmin();
});

